<script lang="ts">
  import type {Snippet} from 'svelte';import Icon from './Icon.svelte';
  export interface WindowModel {id:string;kind:string;title:string;x:number;y:number;width:number;height:number;z:number;minimized:boolean;maximized:boolean;path?:string;restore?:{x:number;y:number;width:number;height:number}}
  let {window:w,active,onfocus,onclose,onminimize,onmaximize,onchange,children}:{window:WindowModel;active:boolean;onfocus:()=>void;onclose:()=>void;onminimize:()=>void;onmaximize:()=>void;onchange:(patch:Partial<WindowModel>)=>void;children:Snippet}=$props();
  function gesture(e:PointerEvent,resize=false){if(e.button!==0||w.maximized)return;e.preventDefault();onfocus();const target=e.currentTarget as HTMLElement;target.setPointerCapture(e.pointerId);const start={x:e.clientX,y:e.clientY,wx:w.x,wy:w.y,width:w.width,height:w.height};const move=(p:PointerEvent)=>{if(resize)onchange({width:Math.min(innerWidth-w.x-8,Math.max(460,start.width+p.clientX-start.x)),height:Math.min(innerHeight-w.y-76,Math.max(280,start.height+p.clientY-start.y))});else onchange({x:Math.min(innerWidth-w.width-8,Math.max(8,start.wx+p.clientX-start.x)),y:Math.min(innerHeight-w.height-76,Math.max(8,start.wy+p.clientY-start.y))});};const stop=()=>{target.removeEventListener('pointermove',move);target.removeEventListener('pointerup',stop);target.removeEventListener('pointercancel',stop);};target.addEventListener('pointermove',move);target.addEventListener('pointerup',stop);target.addEventListener('pointercancel',stop);}
</script>
<section class="desktop-window" class:active class:maximized={w.maximized} style:left={w.maximized?'8px':`${w.x}px`} style:top={w.maximized?'8px':`${w.y}px`} style:width={w.maximized?'calc(100% - 16px)':`${w.width}px`} style:height={w.maximized?'calc(100% - 84px)':`${w.height}px`} style:z-index={w.z} style:display={w.minimized?'none':'flex'} onpointerdown={onfocus} role="group" aria-label={w.title}>
  <header class="window-titlebar" onpointerdown={e=>{if(!(e.target as HTMLElement).closest('button'))gesture(e);}} ondblclick={e=>{if(!(e.target as HTMLElement).closest('button'))onmaximize();}} role="presentation"><span class="window-app-icon"><Icon name={w.kind==='editor'?'file':w.kind} size={17}/></span><span class="window-title">{w.title}</span><div class="window-controls"><button title="Minimize" onpointerdown={e=>e.stopPropagation()} onclick={onminimize}><Icon name="min" size={15}/></button><button title={w.maximized?'Restore':'Maximize'} onpointerdown={e=>e.stopPropagation()} onclick={onmaximize}><Icon name={w.maximized?'restore':'max'} size={14}/></button><button class="close-control" title="Close" onpointerdown={e=>e.stopPropagation()} onclick={onclose}><Icon name="close" size={17}/></button></div></header>
  <div class="window-content">{@render children()}</div>{#if !w.maximized}<div class="resize-grip" onpointerdown={e=>gesture(e,true)} role="presentation"></div>{/if}
</section>
